class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        us = [p[0] + p[1] for p in points]
        vs = [p[0] - p[1] for p in points]

        def top_bottom(arr):
            # returns indices of two largest and two smallest
            order = sorted(range(n), key=lambda i: arr[i])
            low1, low2 = order[0], order[1]
            high1, high2 = order[-1], order[-2]
            return high1, high2, low1, low2

        uh1, uh2, ul1, ul2 = top_bottom(us)
        vh1, vh2, vl1, vl2 = top_bottom(vs)

        best = float('inf')
        for i in range(n):
            # max/min of u excluding i
            if i == uh1:
                maxu = us[uh2]
            else:
                maxu = us[uh1]
            if i == ul1:
                minu = us[ul2]
            else:
                minu = us[ul1]
            if i == vh1:
                maxv = vs[vh2]
            else:
                maxv = vs[vh1]
            if i == vl1:
                minv = vs[vl2]
            else:
                minv = vs[vl1]
            cand = max(maxu - minu, maxv - minv)
            if cand < best:
                best = cand
        return best
