class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        s = [p[0] + p[1] for p in points]
        d = [p[0] - p[1] for p in points]

        def top_bottom(vals):
            order = sorted(range(n), key=lambda i: vals[i])
            # two smallest indices, two largest indices
            mins = order[:2]
            maxs = order[-2:][::-1]
            return mins, maxs

        smin, smax = top_bottom(s)
        dmin, dmax = top_bottom(d)

        def spread_without(i, vals, mins, maxs):
            # max of others
            mx = None
            for j in maxs:
                if j != i:
                    mx = vals[j]
                    break
            mn = None
            for j in mins:
                if j != i:
                    mn = vals[j]
                    break
            return mx - mn

        best = float('inf')
        for i in range(n):
            a = spread_without(i, s, smin, smax)
            b = spread_without(i, d, dmin, dmax)
            best = min(best, max(a, b))
        return best

