        # all equal points
        p = [draw(st.integers(1, 10)), draw(st.integers(1, 10))]
        pts = [list(p) for _ in range(n)]
    elif mode == 1:
        # extremes of the (scaled) range
        pts = [[draw(st.sampled_from([1, 10])), draw(st.sampled_from([1, 10]))] for _ in range(n)]
    elif mode == 2:
        # sorted by x then y (monotone-ish data)
        xs = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
        ys = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
        pts = [[x, y] for x, y in zip(xs, ys)]
    else:
        pts = [[draw(st.integers(1, 10)), draw(st.integers(1, 10))] for _ in range(n)]
    return json.dumps(pts)


